  ],
  "contradictory_card_ids": ["C25"],
  "prediction_basis_card_ids": ["C01","C11","C13"],
  "claims": [
    {
      "claim": "All L1 gold contexts report human oral/systemic bioavailability values at or above 22% (pramipexole >90%, labetalol 63±7%, 5-HTP 49%, cilomilast 96%, PF-05241328 38%, AZD0837 22–55%, isradipine 37%, ebastine ~40%, leucovorin 100%, 1,25(OH)2D2 41±18%).",
      "card_ids": ["C01","C02","C03","C04","C05","C06","C07","C08","C09","C10","C11","C12","C13","C14"]
    },
    {
      "claim": "L2 records confirm or refine these values and do not reveal any sub-20% value: labetalol 63% (vs 33% controls), 5-HTP mouse F=40%, cilomilast 103%, AZD0837 ~22–55%, isradipine 28–37% in cirrhosis, PF-05241328 38%, 1,25(OH)2D2 43±35%.",
      "card_ids": ["C15","C16","C17","C18","C19","C20","C21","C22","C23","C24"]
    },
    {
      "claim": "L3 oral exposure records show measurable oral AUC/Cmax for structurally related small polar/basic molecules (pramipexole ER Tmax; levetiracetam distal-bowel AUC; melatonin and ramosetron Cmax/AUC), but none provides a matched oral-vs-IV F value; they are consistent with oral absorption but not threshold-defining.",
      "card_ids": ["C26","C27","C28","C29","C30","C31","C32","C33","C34","C35","C36","C37"]
    },
    {
      "claim": "The ramosetron-fluvoxamine AUC increase (2.66-fold) indicates CYP-mediated first-pass/clearance for that molecule, but this is not an F measurement and does not affirm F<20% for the query.",
      "card_ids": ["C30","C31","C32"]
    },
    {
      "claim": "The only non-numeric 'low' statement (ebastine, C25) conflicts with L1 C02 (~40%) and is not threshold-specific; it does not affirm F<20%.",
      "card_ids": ["C25","C02"]
    },
    {
      "claim": "The query's full ionization and very low logD are permeability concerns, but structurally relevant polar basic/amide molecules with F≥20% show this does not by itself establish F<20%.",
      "card_ids": ["C01","C11","C13"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C26","C27","C28","C29","C30","C31","C32","C33","C34","C35","C36","C37"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present.",
    "No matched oral-versus-IV AUC/Cmax comparison is supplied for the query or for the L3 reference molecules; L3 Cmax/AUC values alone cannot establish the F=20% threshold.",
    "First-pass metabolism and transporter-mediated absorption for the query are not directly characterized; the ramosetron-fluvoxamine interaction is a metabolism signal for a different molecule only.",
    "The query's very low logD (-1.56) and full ionization at physiological pH leave residual permeability uncertainty not directly resolved by the contexts.",
    "The ebastine 'low' statement (C25) is non-numeric and not threshold-specific."
  ],
  "decision_summary": "L3 oral exposure records add measurable AUC/Cmax for structurally related molecules but no matched IV comparator or F value; they do not overturn the L1/L2 pattern of F≥20% across transferable contexts, including structurally relevant pramipexole, 5-HTP, and labetalol. Prediction remains high with moderate confidence."
}

